const i={ui:{fig:"Рис. 4",title:"Отдельная деталь дна",svgLabel:"Изометрический рисунок того, как вшивают отдельное дно: стенки стачаны в трубу, середины дна и трубы отмечены сгибами, труба изнанкой наружу стоит на дне, метки совмещены и сколоты, припуск стенок у углов надсечён, дно пришито по одной стороне, сумка вывернута — дно ровное.",prev:"Предыдущий шаг",dot:(t,e)=>t?`Шаг ${t}: ${e}`:e,start:"Шаги →",next:"Дальше →",overview:"Обзор",stepOf:(t,e)=>`Шаг ${t} из ${e}`,machine:t=>`Машина: ${t.toLowerCase()}`,inThisStep:"В этом шаге",takeApart:"Поставить",putTogether:"Показать дно",replay:"↻ Повторить",parts:"Детали",allSteps:"Пошаговая инструкция",endView:"ВИД С ТОРЦА"},stitches:{straight:"Прямая строчка"},labels:{rightSides:"лицом к лицу",bothSides:"стачать оба бока",aTube:"труба без дна",foldCrease:"сложить, загладить",markMiddle:"метки на серединах",seamMark:"боковой шов — метка",insideOut:"изнанкой наружу",markOnMark:"метка к метке",clipBetween:"потом сколоть между",clipCorner:"надсечь в угол",notThrough:"не доходя до линии шва",backstitch:"закрепка",oneSide:"по одной стороне",stopTurn:"стоп, поворот",allRound:"и так по кругу",turnOut:"вывернуть на лицо",flatBottom:"ровное дно",baseSeam:"шов по краю дна"},steps:[{title:"Отдельная деталь дна",text:"Дно сумки, сумка перевёрнута: дно скроено отдельной деталью, здесь из другой ткани, и пришито к стенкам по всему краю. Нажмите на сумку, чтобы её поставить."},{title:"Стачать стенки в трубу",text:"Сложите перед и спинку лицом к лицу и стачайте оба бока: получится труба, открытая с обеих сторон. Дно — отдельная деталь.",details:["Сложите перед и спинку лицом к лицу и сколите зажимами.","Стачайте оба бока сверху донизу.","Снизу труба тоже остаётся открытой: дно — отдельная деталь, его вшивают позже.","Если стенки скроены одной деталью, трубу стачивают одним швом."]},{title:"Отметить середины",text:"Сложите дно пополам и загладьте сгиб, потом сложите пополам в другую сторону: отметьте середину каждой его стороны. Трубу тоже сложите пополам и загладьте: сгибы и боковые швы отмечают её середины.",details:["Сложите дно пополам и загладьте сгиб утюгом или пальцами.","Разверните, сложите пополам в другую сторону и снова загладьте.","Поставьте метку на середине каждой стороны, у края, там, где к нему подходит сгиб.","Сложите трубу пополам, боковой шов к боковому шву, и загладьте: сгибы отмечают середину переда и спинки.","Боковые швы — тоже метки: труба, как и дно, размечена на четыре части."]},{title:"Совместить метки",text:"Оставьте трубу изнанкой наружу и поставьте на дно, лицом к лицу, срезы ровно. Сначала совместите метки — боковые швы и сгибы на серединах сторон дна, — потом сколите между ними.",details:["Труба вывернута изнанкой наружу, дно лежит лицом вверх: лицевые стороны смотрят друг на друга.","Выровняйте срезы трубы и дна по всему краю; припуск стенок лежит на краю дна.","Сначала совместите метки: боковой шов — на середину короткой стороны, сгиб — на середину длинной.","Сколите зажимами сначала метки, потом — между ними."]},{title:"Надсечь уголки",text:"У каждого угла дна надсеките ножницами припуск стенок прямо в угол, не доходя до линии шва, строчку не задевая: тогда стенки повернут за угол.",details:["Найдите, где каждый угол дна встречается со стенками.","Надсеките ножницами припуск стенок в угол, почти до линии шва, — не доходя до строчки.","Припуск раскрывается и ложится ровно вокруг угла, а уголок остаётся острым.","Так же надсеките все углы."]},{title:"Пришить дно",text:"Шейте по одной стороне: начните с закрепки, остановитесь на ширину припуска от угла, игла в ткани, поверните работу и шейте следующую сторону.",details:["Шейте изнанкой наружу, по линии шва.","Начните с середины стороны, с закрепки.","Остановитесь на ширину припуска от угла, игла в ткани.","Поднимите лапку, поверните работу, опустите лапку и шейте следующую сторону.","Снимайте зажимы по ходу и пройдите по всему кругу; в конце — закрепка."]},{title:"Вывернуть",text:"Выверните сумку на лицо и выправьте уголки: дно ровное и пришито к стенкам по всему краю.",details:["Выверните сумку на лицо и выправьте уголки.","Дно лежит ровно, шов идёт по его краю.","Если дно должно быть жёстким, укрепляют само дно: клеевой флизелин приутюживают до того, как дно вшить, или потом кладут внутрь жёсткую вставку."]}],legend:[{title:"Дно",text:"отдельная деталь · здесь из другой ткани"},{title:"Шов дна",text:"соединяет стенки с дном по всему краю"},{title:"Уголки",text:"припуск стенок надсечён, поэтому уголок острый"},{title:"Боковые швы",text:"каждый приходит на середину короткой стороны дна"}]};export{i as default};
